// Mock intake counts - swap for helpdesk API: tickets created in the last hour + 4-week same-weekday-same-hour baseline
const lastHour = 31;
const baseline = 12; // avg for this weekday+hour over 4 weeks
const categoriesLastHour = { 'webhook failures': 19, 'how-to': 6, 'billing': 3, 'other': 3 };
return [{ json: { lastHour, baseline, ratio: +(lastHour / Math.max(baseline, 1)).toFixed(2), categoriesLastHour } }];

// A spike is usually one root cause wearing many tickets. Check concentration before panicking about staffing.
const { lastHour, baseline, ratio, categoriesLastHour } = $input.first().json;
const sorted = Object.entries(categoriesLastHour).sort((a, b) => b[1] - a[1]);
const [topCat, topCount] = sorted[0];
const concentration = Math.round(100 * topCount / lastHour);
let read, actions;
if (concentration >= 50) {
  read = 'ONE ROOT CAUSE: ' + concentration + '% of the spike is \"' + topCat + '\". This is an incident wearing ' + topCount + ' tickets.';
  actions = '1. Check status of related systems + recent deploys\n2. Declare an incident if confirmed; one owner, one thread\n3. Post a status note + macro reply so customers get one good answer instead of many slow ones\n4. Link tickets to the incident for one-shot resolution';
} else {
  read = 'DIFFUSE SPIKE: no dominant category (' + topCat + ' at ' + concentration + '%). Likely organic volume.';
  actions = '1. Pull one floater onto the queue for 2 hours\n2. Watch first-response SLA burn (Sentinel will flag at-risk tickets)\n3. Recheck next hour; two diffuse spike hours in a row = staffing conversation, not incident';
}
return [{ json: {
  subject: 'Volume spike: ' + lastHour + ' tickets/hr vs baseline ' + baseline + ' (x' + ratio + ')',
  body: 'Intake spike detected.\n\n' + read + '\n\nCategory breakdown: ' + sorted.map(([c, n]) => c + ' ' + n).join(', ') + '\n\nNext actions:\n' + actions + '\n\nPrinciple: triage the cause, not just the queue.'
} }];
